{
  "status": "designed",
  "request": "Give me a report listing every reaction on messages that were authored by a member of #engineering. I want to know the emoji, the reactor, and the message it was on.",
  "selection_plan": {
    "root_entity": "REACTION",
    "route": "REACTION -> MESSAGE -> USER (author) -> CONVERSATION_MEMBERSHIP -> CONVERSATION (channel_name='engineering')",
    "identifying_criteria": [
      "focal: the message's author (via MESSAGE.user_id) holds a CONVERSATION_MEMBERSHIP in a CONVERSATION whose channels.channel_name = 'engineering'",
      "auxiliary: none beyond the route binding itself (message must have at least one reaction)"
    ],
    "clarifications": "The membership must belong to the message AUTHOR, not the reactor. Reactor identity is not itself constrained by #engineering membership. Multiple reactions on the same qualifying message are distinct referents; multiple qualifying messages by different engineering members each contribute their own reactions."
  },
  "resolution_plan": {
    "mode": "multiple",
    "resolved": true,
    "expected_shape": "A determined collection of REACTION rows (message_id+user_id+reaction_type triples) whose message's author is a member of #engineering. Two authors distinct, each contributing at least one message with 2+ reactions, so the set has at least 4 members, jointly intended as one collection.",
    "notes": "Root count is distinct reaction rows, not distinct messages or authors. A message with several reactions contributes several distinct roots."
  },
  "negative_plan": {
    "near_miss_type": "relationship near-miss (wrong role binding)",
    "description": "A message authored by someone who is NOT a member of #engineering, but which was reacted to by a user who IS a member of #engineering. This satisfies a plausible surface reading ('reactions connected to #engineering people') while failing the focal condition (author must be the #engineering member, not the reactor). Include reactions on this message as decoys that must NOT appear in the answer set.",
    "additional_filler": "A second engineering member who is only ever a reactor (never an author) elsewhere in the seed, to reinforce that reactor-side membership is irrelevant, plus a few ordinary unrelated messages/reactions in other channels with no connection to #engineering at all."
  },
  "environment_plan": "Seed a Slack workspace with a #engineering channel and at least one unrelated channel (e.g. #random). #engineering has 2-3 members including two authors A1 and A2 who each post a message that receives multiple reactions (from a mix of engineering members and outsiders) - these reactions form the true positive set. Add a decoy message authored by a non-member (not in #engineering) that is reacted to by an #engineering member (the near-miss), whose reactions must be excluded. Add filler messages/reactions in #random unconnected to #engineering membership. Give every referenced user a single deterministic workspace membership per runtime qualifications. Use opaque IDs (U-prefixed, C-prefixed, T-prefixed) and realistic usernames/timestamps.",
  "action_plan": "1. Identify #engineering's channel_id via conversations.list/conversations.info (Card 1: CONVERSATION). 2. Retrieve #engineering's membership roster via conversations.members (Card 1). 3. Retrieve message history for all readable channels via conversations.history, noting each message's author (Card 2: MESSAGE/USER binding). 4. For each message authored by a user present in the #engineering roster, retrieve its reactions via reactions.get (Card 3: REACTION, the requested referent set). 5. Compile a report of emoji/reactor/message for exactly the reactions gathered in step 4, excluding reactions on messages authored by non-members regardless of reactor identity.",
  "reason": null
}
